): Promise<AgentRuntime> {
  const raw = await this.fetch<unknown>(`/api/runtimes/${runtimeId}`, {
    method: "PATCH",
    body: JSON.stringify(patch),
  });
  return parseWithFallback(raw, AgentRuntimeSchema, EMPTY_RUNTIME, { endpoint: "updateRuntime" });
}

